const summaryOpenPolicyAlerts = `-- name: SummaryOpenPolicyAlerts :many
SELECT a.kind, a.created_at, d.id AS device_id, d.rustdesk_id, d.alias, d.hostname,
       COALESCE((SELECT string_agg(g.name, ', ' ORDER BY g.name COLLATE "C", g.id)
                 FROM device_groups g
                 WHERE g.id::text IN (SELECT jsonb_array_elements_text(a.details->'group_ids'))
                   AND ($1::uuid IS NULL OR g.id IN (SELECT visible_groups($1::uuid)))), '')::text AS group_names
FROM device_alerts a JOIN devices d ON d.id = a.device_id
WHERE a.resolved_at IS NULL AND a.kind IN ('uuid_mismatch', 'access_window_unconfirmed', 'group_conflict')
  AND (a.kind <> 'group_conflict' OR d.state = 'approved')
  AND ($1::uuid IS NULL OR d.id IN (SELECT visible_devices($1::uuid)))
`

type SummaryOpenPolicyAlertsRow struct {
	Kind       string
	CreatedAt  time.Time
	DeviceID   uuid.UUID
	RustdeskID string
	Alias      string
	Hostname   string
	GroupNames string
}

func (q *Queries) SummaryOpenPolicyAlerts(ctx context.Context, scopeUser *uuid.UUID) ([]SummaryOpenPolicyAlertsRow, error) {
	rows, err := q.db.Query(ctx, summaryOpenPolicyAlerts, scopeUser)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SummaryOpenPolicyAlertsRow
	for rows.Next() {
		var i SummaryOpenPolicyAlertsRow
		if err := rows.Scan(
			&i.Kind,
			&i.CreatedAt,
			&i.DeviceID,
			&i.RustdeskID,
			&i.Alias,
			&i.Hostname,
			&i.GroupNames,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updatePolicy = `-- name: UpdatePolicy :one
UPDATE client_policies SET name = $1, settings = $2,
    updated_at = $3, updated_by = $4
WHERE id = $5 RETURNING id, name, settings, is_default, created_at, updated_at, updated_by
`

type UpdatePolicyParams struct {
	Name      string
	Settings  []byte
	UpdatedAt time.Time
	UpdatedBy *uuid.UUID
	ID        uuid.UUID
}

func (q *Queries) UpdatePolicy(ctx context.Context, arg UpdatePolicyParams) (ClientPolicy, error) {
	row := q.db.QueryRow(ctx, updatePolicy,
		arg.Name,
		arg.Settings,
		arg.UpdatedAt,
		arg.UpdatedBy,
		arg.ID,
	)
	var i ClientPolicy
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Settings,
		&i.IsDefault,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.UpdatedBy,
	)
	return i, err
}
